<script setup lang="ts">import {ref} from 'vue';import type {Workspace} from '../stores/workspace';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';import RateSummary from '../components/RateSummary.vue';import {create} from '../api/profiles';import {useAsync} from '../hooks/useAsync';import {number} from '../utils/format';import {PERIODS} from '../constants/enums';const props=defineProps<{data:Workspace;canWrite:boolean;refresh:()=>Promise<void>}>();const name=ref(''),dataset=ref(''),period=ref('all');const {busy,error,execute}=useAsync();async function submit(){await execute(async()=>{await create({name:name.value,dataset_id:dataset.value||props.data.datasets[0]?.id,period:period.value});name.value='';await props.refresh()})};
</script><template><PageHeading code="03 / SERVICE PROFILE" title="先说明每分钟发生什么。" description="λ = 1 / 平均到达间隔；μ = 1 / 平均服务时长。μ是单个窗口的服务率，不是全部窗口的合计。"/><section v-if="canWrite" class="paper"><h2>由观测估计输入率</h2><form class="grid-form" @submit.prevent="submit"><label>剖面名称<input aria-label="剖面名称" required minlength="2" v-model="name"/></label><label>观测集<select aria-label="剖面观测集" v-model="dataset"><option value="" disabled>默认使用最新观测集</option><option v-for="d in data.datasets" :key="d.id" :value="d.id">{{d.name}}</option></select></label><label>时段口径<select aria-label="时段口径" v-model="period"><option value="all">全日</option><option value="peak">高峰</option><option value="offpeak">平峰</option></select></label><button :disabled="busy">计算并保存剖面</button></form><Notice v-if="error" error>{{error}}</Notice></section><section class="paper" v-for="p in data.profiles" :key="p.id"><div class="section-heading"><h2>{{p.name}}</h2><span>{{PERIODS[p.period]}} · n={{p.statistics.n}}</span></div><RateSummary :profile="p"/><div class="profile-assumption"><div><small>到达间隔变异系数</small><b>{{number(p.statistics.interarrival_cv)}}</b></div><div><small>服务时长变异系数</small><b>{{number(p.statistics.service_cv)}}</b></div><p>指数分布的理论CV为1。均值与CV仅作口径核查，不能据此证明独立、泊松或稳态假设。</p></div><small>输入校验码 {{p.statistics.checksum.slice(0,20)}}</small></section></template>
